INSERT INTO heritage_items (target_id, name, year, description, location, current_status, image_path) VALUES
('abusimbel', '阿布辛贝神庙', '约公元前1264年', '阿布辛贝神庙是古埃及法老拉美西斯二世的惊世之作，直接在尼罗河西岸的整座山体中开凿而成。神庙正面是四尊高达20米的法老坐像，宛如巨神守护入口。最神奇的是“太阳节”奇观：每年2月22日和10月22日，初升太阳的光芒会穿过60米深的殿堂，精准照在神龛中拉美西斯二世、阿蒙神和拉·哈拉赫提神的脸上，唯有冥界之神普塔赫永远留在黑暗中。1960年代因兴建阿斯旺大坝，整座神庙被切割成上千块，整体搬迁至高处，堪称现代工程与考古的壮举。', '埃及阿斯旺省，纳赛尔湖西岸', '世界文化遗产，埃及重要旅游景点', 'abusimbel.jpg'),
('angelfalls', '安赫尔瀑布', '自然景观', '安赫尔瀑布藏身于委内瑞拉东南部的卡奈马国家公园，落差高达979米，是全世界落差最大的瀑布。水流从奥扬特普伊山的平顶边缘倾泻而下，在撞击崖壁的瞬间化为漫天白雾，远看宛如天使的羽翼，因此得名“天使瀑布”。由于高度实在惊人，大部分水珠未及地面便已蒸发成云，形成“水从天上落，半途化作雨”的奇观。瀑布所在的“失落的世界”正是动画电影《飞屋环游记》天堂瀑布的灵感原型，至今只能乘小飞机或独木舟深入原始丛林一睹真容。', '委内瑞拉玻利瓦尔州卡奈马国家公园', '世界自然遗产，委内瑞拉最著名的自然奇观', 'angelfalls.jpg'),
('bentpyramid', '弯曲金字塔', '约公元前2600年', '弯曲金字塔是古埃及金字塔演化史上的“错版杰作”。它由法老斯尼夫鲁建造，底角一开始设计得过于陡峭（约54°），建到一半工程师发现结构不稳、石材开裂，紧急把倾角改为较缓的43°，于是造就了这座全世界独一无二的“弯腰”金字塔。这看似失误的建筑，却意外保留了金字塔从阶梯式向光滑斜面过渡的关键证据，堪称建筑史活化石。它高达101米，外层覆石至今部分完好，远远望去像一顶巨大的白色帐篷，静静地诉说着四千多年前的试错与智慧。', '埃及代赫舒尔金字塔区', '世界文化遗产（孟菲斯及其墓地金字塔群的一部分）', 'bentpyramid.jpg'),
('burjkhalifa', '哈利法塔', '2010年', '哈利法塔是人类建筑野心直插云霄的宣言，总高828米，以近乎不可思议的姿态把“世界最高”纪录推向了新高度。整座大楼灵感源自沙漠之花蜘蛛兰的几何对称，采用Y形楼层布局，如一把利剑刺向波斯湾的天空。它集酒店、豪宅、办公室和观景台于一体，第148层的观景台曾是全球最高，站在上面可将棕榈岛与阿拉伯沙漠尽收眼底。塔身由26,000多块玻璃面板包裹，日落时分整座塔就像燃烧的火焰，是迪拜从渔村变成未来之城的终极象征。', '阿拉伯联合酋长国迪拜谢赫扎耶德路1号', '世界最高建筑，迪拜核心地标', 'burjkhalifa.jpg'),
('chichenitza', '奇琴伊察', '约公元6世纪', '奇琴伊察是玛雅文明最辉煌的城邦之一，金字塔“库库尔坎”是其心跳。这座30米高的神殿以极其精确的天文历法设计：四面各91级台阶，加上顶部平台正好365级，代表一年；每年春分秋分的黄昏，阶梯侧墙会投射出蛇形光影，仿佛羽蛇神正从塔顶蜿蜒而下。遗址内还有巨大的古代球场、千柱市场和神秘的“圣井”，献祭与观星交织。玛雅人在没有金属工具和轮子的情况下雕琢出如此精确的建筑，令人对这片中美洲丛林中的石城肃然起敬。', '墨西哥尤卡坦半岛', '世界文化遗产，世界新七大奇迹之一', 'chichenitza.jpg'),
('christ', '基督救世主像', '1931年', '里约热内卢的基督像张开28米宽的双臂，仿佛要拥抱整座城市。这座高达38米的巨型雕塑矗立在710米高的科科瓦多山顶，由巴西、法国和波兰的艺术家联手完成，外部贴满三角形手工皂石马赛克。无论你在里约的哪个角落，一抬头几乎都能看到祂的剪影映衬着大西洋的蓝天。入夜后灯光亮起，基督像又像悬浮在黑暗中的光明灯塔。它不仅是巴西的标志，更被列为世界新七大奇迹之一，守护着这座山海之间的狂欢之城。', '巴西里约热内卢科科瓦多山', '世界新七大奇迹之一，巴西国家文化遗产', 'christ.jpg'),
('djoser', '左塞尔金字塔', '约公元前2667年', '左塞尔金字塔是埃及现存最古老的金字塔，也是人类历史上第一座完全用石材砌成的巨型建筑。它由天才宰相伊姆霍特普设计，一改之前的泥砖墓穴，以六个逐层缩小的方形平台叠成60米高的六层阶梯，带领法老走向永生。整座建筑坐落在广阔的萨卡拉墓区，外围有精美的石墙和柱廊，仿佛一座为灵魂打造的石头宫城。伊姆霍特普后来被奉为医神和建筑之神，这座阶梯金字塔便是他辉煌想象力的起点，比胡夫金字塔早近一个世纪。', '埃及萨卡拉墓地', '世界文化遗产（孟菲斯及其墓地金字塔群的一部分）', 'djoser.jpg'),
('hatshepsut', '哈特谢普苏特神庙', '约公元前15世纪', '哈特谢普苏特神庙是古埃及最独特的葬祭殿，如同一座现代三层露台嵌入代尔巴哈里悬崖绝壁之下。女法老哈特谢普苏特为彰显统治合法性，采用层层退台的柱廊设计，长坡道缓缓上升，与垂直崖壁形成雄浑的几何对话。柱廊墙上满布浮雕，记录着她远征神秘的蓬特之地带回香料、象牙和异兽的功绩。神庙曾被后世法老刻意破坏，又因山体崩塌深埋千年，如今修复后的白色石灰岩立面在烈日下闪闪发光，诉说着这位女法老传奇而曲折的一生。', '埃及卢克索尼罗河西岸', '世界文化遗产（底比斯古城及其墓地的一部分）', 'hatshepsut.jpg'),
('liberty', '自由女神像', '1886年', '自由女神像是法国人民送给美国独立100周年的巨型礼物，由雕塑家巴托尔迪设计，以他母亲的面容和妻子身体为蓝本。铜像高46米，加上基座达93米，高举火炬引导航船，脚下是打碎的铁链，象征挣脱暴政。整座雕像以锻铜皮包裹铁骨架，内部结构正是埃菲尔铁塔设计师古斯塔夫·埃菲尔的手笔。百年来她默默守卫纽约港，是无数移民踏入美国时看到的第一个身影，被列为世界文化遗产，用沉默的铜绿讲述自由与希望的故事。', '美国纽约自由岛', '世界文化遗产，美国国家纪念碑', 'liberty.jpg'),
('machupicchu', '马丘比丘', '约公元1450年', '马丘比丘是印加帝国遗落在云雾中的天空之城，坐拥海拔2430米的山脊，俯瞰乌鲁班巴河峡谷。整座古城精确地切割石头，连灰泥都无需使用，石缝密合得连刀片都插不进。梯田、太阳神庙、拴日石和水渠系统构成完美的山巅聚落。因西班牙征服者从未抵达，它得以完好封存了印加文明的精髓，直到1911年才被重新发现。羊驼在古老石墙间漫步，晨雾从深谷翻腾而上，仿佛时间在此凝固，是世界新七大奇迹中最为神秘的存在之一。', '秘鲁库斯科省乌鲁班巴省', '世界文化与自然双重遗产，世界新七大奇迹之一', 'machupicchu.jpg'),
('memnon', '门农巨像', '约公元前1350年', '门农巨像是两尊高达18米的石像，端坐在卢克索尼罗河西岸的旷野中，实际代表的是法老阿蒙霍特普三世，身后本是其宏伟的葬祭殿，今已湮灭。传说地震损坏北侧巨像后，石像在黎明时分会发出类似竖琴弦断的鸣响，希腊人浪漫地认为是特洛伊英雄门农在向母亲曙光女神厄俄斯哭泣。实际上那是石缝热胀冷缩的物理现象，但罗马皇帝哈德良都曾专程前来聆听这“神之叹息”。如今石像已修复不再“唱歌”，但依然孤寂庄严地守望着千年日升月落。', '埃及卢克索尼罗河西岸', '世界文化遗产（底比斯古城及其墓地的一部分）', 'memnon.jpg'),
('petra', '佩特拉古城', '约公元前4世纪', '佩特拉是纳巴泰人在玫瑰色砂岩峡谷中雕凿出的绝代都城。穿过仅容两人并行的1.2公里长蛇道“西克”，豁然耸立的就是高达40米的卡兹尼神殿——整座建筑直接在石壁上掏刻而成，立面精雕细刻，传说曾藏有法老的宝藏。城中还有剧场、墓室和引水渠，全凭古人利用岩壁和暗渠收集每一滴雨水。阳光不同时分，岩石会从粉色变为深红、橙黄，被称“玫瑰古城”。它是丝绸之路的重要枢纽，被列为世界新七大奇迹之一，宛如时间与岩石合写的史诗。', '约旦马安省', '世界文化遗产，世界新七大奇迹之一', 'petra.jpg'),
('ramesseum', '拉美西姆神庙', '约公元前13世纪', '拉美西姆神庙是拉美西斯二世的葬祭殿，也是诗人雪莱笔下《奥兹曼迪亚斯》的灵感来源。走进遗址，横亘在地的巨大花岗岩雕像残骸震撼人心，原高17米的坐像倒塌后化为碎片，脚趾都比人高，印证了法老渴望万世不朽的野心。神庙墙壁浮雕描绘着著名的卡迭石战役，拉美西斯二世单驾战车反击赫梯大军，画面动感十足。拱顶仓库的泥砖遗迹则揭示当年庞大的粮储系统。如今在阳光下断柱残垣更显苍凉，无愧为“帝国余晖”的最佳注脚。', '埃及卢克索尼罗河西岸', '世界文化遗产（底比斯古城及其墓地的一部分）', 'ramesseum.jpg'),
('colosseum', '罗马斗兽场', '公元80年', '罗马斗兽场是古罗马帝国残酷娱乐的巅峰剧场，最多可容纳8万观众，通过80个拱门快速疏散，设计至今影响现代体育场。三层环形拱廊分别采用多立克、爱奥尼和科林斯柱式，堪称古典柱式教科书。地底下复杂的兽笼与升降机关，能让猛兽和角斗士瞬间出现在铺满沙子的舞台上。角斗士血与沙的故事在此上演了数百年，它见证过帝国的荣耀与野蛮。虽经地震和劫掠，残缺的椭圆巨环依然矗立，是罗马乃至整个欧洲文明的永恒象征，世界新七大奇迹之一。', '意大利罗马', '世界文化遗产，世界新七大奇迹之一', 'colosseum.jpg'),
('sphinx', '狮身人面像', '约公元前2500年', '吉萨的狮身人面像是人类艺术史上最硕大的谜题，全长73.5米，高20米，以整块石灰岩直接雕成。它有着法老哈夫拉的头颅和雄狮的身躯，象征智慧与力量，面朝东方守护金字塔已逾4500年。拿破仑炮击的痕迹传说未必属实，但风化与人为破坏让它失去了鼻子和胡须。古希腊人将其视为怪物斯芬克斯，而阿拉伯人称它为“恐怖之父”。沙丘曾多次将它埋至脖颈，如今它静静伏卧在吉萨高原，以残缺的神秘微笑俯瞰尼罗河，任凭岁月流沙。', '埃及吉萨省吉萨高原', '世界文化遗产（吉萨金字塔群的一部分）', 'sphinx.jpg'),
('stonehenge', '巨石阵', '约公元前3000年～2000年', '巨石阵是英伦三岛最神秘的史前遗迹，若干根重达25吨的蓝砂岩巨柱排成环形，顶置水平楣石，在索尔兹伯里平原上伫立了五千年。夏至日出时分，太阳会精准地从“踵石”后方升起，光轴直穿巨石拱门，昭示着它必定是一座精密的天文观测台或祭祀圣地。这些巨岩部分竟来自250公里外的威尔士山区，古人的运输与搭建技术至今成谜。围绕它的德鲁伊祭司、外星人干预和治愈传说层出不穷，而它始终沉默如谜，是刻在大地上的最古老钟表。', '英国威尔特郡索尔兹伯里平原', '世界文化遗产，英国最著名的史前遗址', 'stonehenge.jpg'),
('tajmahal', '泰姬陵', '1653年', '泰姬陵是莫卧儿皇帝沙贾汗为爱妻玛穆塔兹倾国之力修建的白色大理石陵墓，被誉为“永恒之泪”。整个建筑群对称完美，中央穹顶高73米，四座宣礼塔微微外倾以防倒塌时伤及主殿。墙壁镶满用玛瑙、绿松石、青金石雕成的花朵图案，晨光中呈现粉色，月光下又化为银蓝。据说沙贾汗原计划在河对岸为自己建一座全黑陵墓与之呼应，却因被儿子囚禁而抱憾。泰姬陵跨越生死与王朝，是人类建筑中最纯粹的爱情诗篇，世界新七大奇迹之一。', '印度北方邦阿格拉', '世界文化遗产，世界新七大奇迹之一', 'tajmahal.jpg'),
('eiffel', '埃菲尔铁塔', '1889年', '埃菲尔铁塔，人称“铁娘子”，是巴黎当之无愧的超级地标。当年为迎接1889年世界博览会，设计师古斯塔夫·埃菲尔用18038个铁制构件和250万颗铆钉，像搭巨型积木一样，建起了这座当时全世界最高的人造建筑（含天线330米）。它最初被不少文化名流骂作“钢铁怪物”，如今却成了浪漫与创新的象征。塔身总重约10100吨，却显得轻盈通透，每年来打卡的游客多达700万人次，已被列入世界文化遗产。', '法国巴黎战神广场', '列入世界文化遗产，年接待游客约700万人次', 'eiffel.jpg'),
('greatwall', '中国长城', '春秋至明代', '长城是古代中国的超级防御系统，像一条石砌的巨龙盘踞在崇山峻岭间。它从春秋战国就开始修筑，现存最完好的明长城东起辽宁虎山，西到甘肃嘉峪关，总长超过2.1万公里——比地球赤道周长的一半还多。墙体高约两三层楼，顶部宽得可以并排跑马，沿线密布着烽燧、敌楼和关隘。长城不只是一道墙，更是集预警、驻防于一体的军事智慧杰作，被誉为“世界第七大奇迹”，1987年列入世界文化遗产。', '中国北部，横跨15个省级行政区', '世界文化遗产，国家5A级旅游景区', 'greatwall.jpg'),
('potala', '布达拉宫', '公元7世纪（初建），17世纪（重建）', '布达拉宫仿佛从拉萨红山上生长出来的巨大宫殿，红白相间，直入云端。它最早是吐蕃赞普松赞干布为迎娶文成公主而建，17世纪又由五世达赖喇嘛重建，成为历代达赖的冬宫和政教中枢。整座建筑高达200多米，外观13层，实则9层，内有上万间房屋，珍藏着海量壁画、唐卡和佛像，建筑风格融合了藏、汉、尼泊尔的艺术精华。这座“世界屋脊上的明珠”1994年成为世界文化遗产，是西藏最璀璨的人文符号。', '中国西藏自治区拉萨市城关区', '世界文化遗产，全国重点文物保护单位', 'potala.jpg'),
('pyramid', '吉萨金字塔', '约公元前2560年（胡夫金字塔）', '吉萨金字塔群是古埃及法老通往永恒的巨型陵墓。最大的胡夫金字塔原高约146.6米，相当于40层摩天大楼，在埃菲尔铁塔出现前，它牢牢占据“世界最高建筑”宝座将近4000年！塔身用约230万块巨石砌成，平均每块重2.5吨，最重的达15吨，其底面正方形边长误差竟小于0.1°，古埃及人的数学与天文水准高得离谱。它是古代世界七大奇迹中唯一存世至今的，堪称石头的史诗。', '埃及吉萨省吉萨高原', '世界文化遗产，埃及主要旅游景点', 'pyramid.jpg'),
('huangguoshu', '黄果树瀑布', '自然景观', '黄果树瀑布是亚洲最大的瀑布，近百米宽的水幕从77.8米高的悬崖轰鸣而下，水量充沛时气势如万马奔腾。最绝的是瀑布背后藏着一条134米长的水帘洞，游人可穿行其中，隔着水帘感受震耳欲聋的冲击力——这正是《西游记》水帘洞的灵感源头。明代旅行家徐霞客曾用“珠帘钩不卷，飞练挂遥峰”赞美它。周围还有18个形态各异的瀑布，组成了世界上规模最大的瀑布群。', '中国贵州省安顺市镇宁县', '国家5A级旅游景区，国家重点风景名胜区', 'huangguoshu.jpg'),
('leifeng', '雷峰塔', '公元977年（初建），2002年（重建）', '雷峰塔因《白蛇传》白娘子被镇压的传说而家喻户晓，给这座古塔添了一层浪漫悲情的滤镜。它原本是北宋吴越国王为供奉佛舍利而建，却在1924年轰然倒塌。现在的塔是2002年采用钢架重建的现代建筑，以铜瓦覆顶，巧妙地将原塔遗址保护在基座内，游客可透过玻璃地板直视千年塔基。登塔远眺，“雷峰夕照”的绝美画面与西湖烟波尽收眼底，仿佛一眼千年。', '中国浙江省杭州市西湖区夕照山', '国家AAAAA级旅游景区，西湖十景之一', 'leifeng.jpg'),
('qomolangma', '珠穆朗玛峰', '自然景观', '珠穆朗玛峰是当之无愧的地球之巅，中尼联合公布最新海拔8848.86米，而且它还在以每年约4毫米的速度悄然“长高”。峰顶气温可低至-60℃，风速堪比超强台风，环境极端恶劣。1953年人类首次成功登顶，至今已有超过6000人次站上这世界最高处。珠峰地区孕育了壮阔的冰川与独特的山地生态，既是登山者毕生的终极梦想，也是科学家研究地球的天然实验室。', '中国-尼泊尔边界，喜马拉雅山脉中段', '世界自然遗产（尼泊尔侧），国家级自然保护区', 'qomolangma.jpg'),
('threepagoda', '崇圣寺三塔', '公元9世纪（南诏时期）', '大理崇圣寺三塔是大理最经典的封面照。主塔千寻塔高近70米，像一根直刺苍穹的巨型石笋，旁边两座小塔如忠诚护卫。大理地处地震带，可千百年来历经多次大地震（包括1925年7级强震），三塔始终“晃而不倒”，足见古代白族工匠对抗震设计的超凡理解。它们曾是南诏、大理国的皇家寺院遗珍，如今寺院虽已不存，三塔依然静静守护着苍山洱海，1961年被列入首批全国重点文保。', '中国云南省大理市苍山应乐峰下', '全国重点文物保护单位，国家AAAAA级旅游景区', 'threepagoda.jpg'),
('heaven', '天坛', '明永乐十八年（1420年）', '天坛是明清皇帝跟上天“连线”的地方，专为祭天、祈谷而建，占地达273万平方米，比故宫还大。这里的建筑处处暗藏玄机：祈年殿高38米，没用一个横梁，仅凭28根金丝楠木巨柱撑起三层蓝瓦圆顶，分别象征四季、十二月和二十八星宿。圜丘坛和回音壁利用声波反射，能产生奇妙的传音效果，站在中央轻声一呼，回音缭绕。整体布局遵循“天圆地方”的宇宙观，1998年成为世界文化遗产，是中国礼制建筑的登峰造极之作。', '中国北京市东城区天坛内东里甲1号', '世界文化遗产，国家AAAAA级旅游景区', 'heaven.jpg');
